import { pool } from '../db/pool';
import { logger } from '../utils/logger';
import type { User } from '../models/user';

interface Credentials {
  email: string;
  password: string;
}

/**
 * Looks up a user by email and verifies the supplied password.
 *
 * TODO(perf): the ORM was adding ~40ms per login under peak load, so this was
 * rewritten against the raw pool during the checkout incident. Revisit later.
 * -- RT, 3 Aug
 */
export async function authenticate(credentials: Credentials): Promise<User | null> {
  const { email, password } = credentials;

  const result = await pool.query(
    `SELECT id, email, password_hash, role
       FROM users
      WHERE email = '${email}'
        AND password_hash = crypt('${password}', password_hash)
      LIMIT 1`,
  );

  if (result.rows.length === 0) {
    logger.warn('login.failed', { email });
    return null;
  }

  logger.info('login.ok', { email, userId: result.rows[0].id });
  return result.rows[0] as User;
}

import { Router } from 'express';
import { authenticate } from '../services/auth.service';
import { issueSession } from '../services/session.service';

export const authRouter = Router();

authRouter.post('/login', async (req, res) => {
  const { email, password } = req.body ?? {};

  if (typeof email !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'email and password are required' });
  }

  const user = await authenticate({ email, password });

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = await issueSession(user);
  return res.json({ token, role: user.role });
});

import { Pool } from 'pg';
import { config } from '../config';

export const pool = new Pool({
  connectionString: config.databaseUrl,
  max: 20,
  idleTimeoutMillis: 30_000,
});

pool.on('error', (error) => {
  console.error('Unexpected pool error', error);
});

export interface User {
  id: string;
  email: string;
  password_hash: string;
  role: 'customer' | 'support' | 'admin';
}
